# Essential imports (guaranteed to be available)
import os
import torch
import torch.nn as nn
import torch.nn.functional as F
import torch.optim as optim
from dataset import get_dataloader
import json
from tqdm import tqdm
import numpy as np
from sklearn.metrics import roc_auc_score


# Data loading setup
DATA_DIR = "/mnt/disks/data/birdclef"
METADATA_FILE = os.path.join(DATA_DIR, "train.csv")
train_loader = get_dataloader(DATA_DIR, METADATA_FILE, batch_size=32)

# Model Definition
class BirdCNN(nn.Module):
    def __init__(self, num_classes=234):
        super(BirdCNN, self).__init__()
        self.conv1 = nn.Conv2d(1, 32, kernel_size=(3, 3), stride=1, padding=1)
        self.conv2 = nn.Conv2d(32, 64, kernel_size=(3, 3), stride=1, padding=1)
        self.conv3 = nn.Conv2d(64, 128, kernel_size=(3, 3), stride=1, padding=1)
        self.pool = nn.MaxPool2d(kernel_size=(2, 2), stride=2, padding=0)
        self.adaptive_pool = nn.AdaptiveAvgPool2d((1, 1))
        self.fc1 = nn.Linear(128, 512)
        self.fc2 = nn.Linear(512, num_classes)
    
    def forward(self, x):
        x = self.pool(F.relu(self.conv1(x)))
        x = self.pool(F.relu(self.conv2(x)))
        x = self.pool(F.relu(self.conv3(x)))
        x = self.adaptive_pool(x)
        x = x.view(x.size(0), -1)
        x = F.relu(self.fc1(x))
        x = torch.sigmoid(self.fc2(x))
        return x

# Model, Loss Function, and Optimizer
device = torch.device('cuda' if torch.cuda.is_available() else 'cpu')
model = BirdCNN().to(device)
criterion = nn.BCELoss()
optimizer = optim.Adam(model.parameters(), lr=0.001)

# Training Loop
num_epochs = 3
total_steps = len(train_loader) * num_epochs
train_loss_history = []

for epoch in tqdm(range(num_epochs), desc="Epochs"):
    model.train()
    running_loss = 0.0
    for i, (inputs, labels) in enumerate(train_loader):
        if i > 5000 / train_loader.batch_size:  # Limit to first ~5000 samples
            break
        inputs, labels = inputs.to(device), labels.float().to(device)
        
        optimizer.zero_grad()
        outputs = model(inputs)
        loss = criterion(outputs, labels)
        loss.backward()
        optimizer.step()
        
        running_loss += loss.item()
    
    epoch_loss = running_loss / len(train_loader)
    train_loss_history.append(epoch_loss)
    print(f'Epoch [{epoch+1}/{num_epochs}], Loss: {epoch_loss:.4f}')
    torch.cuda.empty_cache()

# Evaluation
model.eval()
all_preds = []
all_labels = []
with torch.no_grad():
    for inputs, labels in train_loader:
        if i > 5000 / train_loader.batch_size:  # Limit to first ~5000 samples
            break
        inputs, labels = inputs.to(device), labels.cpu().numpy()
        outputs = model(inputs)
        all_preds.append(outputs.cpu().numpy())
        all_labels.append(labels)

all_preds = np.concatenate(all_preds)
all_labels = np.concatenate(all_labels)

# Calculate AUC
try:
    final_auc = float(roc_auc_score(all_labels, all_preds, average='weighted', multi_class='ovr'))
except:
    final_auc = float(roc_auc_score(all_labels.ravel(), all_preds.ravel()))

# Metrics and Model Saving
num_params = sum(p.numel() for p in model.parameters())
metrics = {
    "final_train_loss": train_loss_history[-1],
    "final_auc": final_auc,
    "num_params": num_params,
    "epochs_trained": num_epochs,
    "batch_size": train_loader.batch_size
}

print("METRICS: " + json.dumps(metrics))
with open('metrics.json', 'w') as f:
    json.dump(metrics, f)

torch.save(model.state_dict(), 'model.pt')